// axil_timer: 32-bit down-counting timer with one-shot and periodic modes and
// a level interrupt, behind an AXI4-Lite subordinate port.
// Interface: interface_spec.md. Implementation plan: microarchitecture.md.
module axil_timer #(
    parameter integer ADDR_WIDTH = 4
) (
    input  wire                  aclk,
    input  wire                  aresetn,
    input  wire [ADDR_WIDTH-1:0] s_axil_awaddr,
    input  wire                  s_axil_awvalid,
    output wire                  s_axil_awready,
    input  wire [31:0]           s_axil_wdata,
    input  wire [3:0]            s_axil_wstrb,
    input  wire                  s_axil_wvalid,
    output wire                  s_axil_wready,
    output wire [1:0]            s_axil_bresp,
    output wire                  s_axil_bvalid,
    input  wire                  s_axil_bready,
    input  wire [ADDR_WIDTH-1:0] s_axil_araddr,
    input  wire                  s_axil_arvalid,
    output wire                  s_axil_arready,
    output wire [31:0]           s_axil_rdata,
    output wire [1:0]            s_axil_rresp,
    output wire                  s_axil_rvalid,
    input  wire                  s_axil_rready,
    output wire                  irq
);

  localparam [1:0] RESP_OKAY   = 2'b00;
  localparam [1:0] RESP_SLVERR = 2'b10;
  localparam [1:0] IDX_CTRL    = 2'd0;
  localparam [1:0] IDX_LOAD    = 2'd1;
  localparam [1:0] IDX_COUNT   = 2'd2;
  localparam [1:0] IDX_STATUS  = 2'd3;

  // ------------------------------------------------------------------
  // State registers
  // ------------------------------------------------------------------
  reg                  aw_held_q;
  reg                  w_held_q;
  reg [ADDR_WIDTH-1:0] awaddr_q;
  reg [31:0]           wdata_q;
  reg [3:0]            wstrb_q;
  reg                  bvalid_q;
  reg [1:0]            bresp_q;
  reg                  rvalid_q;
  reg [31:0]           rdata_q;
  reg [1:0]            rresp_q;
  reg                  en_q;
  reg                  ie_q;
  reg                  mode_q;
  reg                  expired_q;
  reg [31:0]           load_q;
  reg [31:0]           count_q;

  // Next-state values
  reg                  aw_held_d;
  reg                  w_held_d;
  reg [ADDR_WIDTH-1:0] awaddr_d;
  reg [31:0]           wdata_d;
  reg [3:0]            wstrb_d;
  reg                  bvalid_d;
  reg [1:0]            bresp_d;
  reg                  rvalid_d;
  reg [31:0]           rdata_d;
  reg [1:0]            rresp_d;
  reg                  en_d;
  reg                  ie_d;
  reg                  mode_d;
  reg                  expired_d;
  reg [31:0]           load_d;
  reg [31:0]           count_d;

  // ------------------------------------------------------------------
  // Write channels
  // ------------------------------------------------------------------
  wire                  awready_w = !aw_held_q && !bvalid_q;
  wire                  wready_w  = !w_held_q && !bvalid_q;
  wire                  aw_hs     = s_axil_awvalid && awready_w;
  wire                  w_hs      = s_axil_wvalid && wready_w;
  wire                  do_write  = (aw_held_q || aw_hs) && (w_held_q || w_hs);
  wire [ADDR_WIDTH-1:0] wr_addr   = aw_held_q ? awaddr_q : s_axil_awaddr;
  wire [31:0]           wr_data   = w_held_q ? wdata_q : s_axil_wdata;
  wire [3:0]            wr_strb   = w_held_q ? wstrb_q : s_axil_wstrb;
  wire                  wr_hi;
  wire                  wr_mapped = (wr_addr[1:0] == 2'b00) && !wr_hi;
  wire [1:0]            wr_idx    = wr_addr[3:2];
  wire                  wr_okay   = wr_mapped && (wr_idx != IDX_COUNT);
  wire                  ctrl_wr   = do_write && wr_mapped && (wr_idx == IDX_CTRL) && wr_strb[0];
  wire                  load_wr   = do_write && wr_mapped && (wr_idx == IDX_LOAD);
  wire                  status_clr = do_write && wr_mapped && (wr_idx == IDX_STATUS) &&
                                     wr_strb[0] && wr_data[0];

  // ------------------------------------------------------------------
  // Read channels
  // ------------------------------------------------------------------
  wire                  arready_w = !rvalid_q;
  wire                  ar_hs     = s_axil_arvalid && arready_w;
  wire                  rd_hi;
  wire                  rd_mapped = (s_axil_araddr[1:0] == 2'b00) && !rd_hi;
  wire [1:0]            rd_idx    = s_axil_araddr[3:2];
  reg  [31:0]           rd_value;

  // Offsets from 0x10 up are unmapped and must never alias a register.
  generate
    if (ADDR_WIDTH > 4) begin : g_hi_bits
      assign wr_hi = |wr_addr[ADDR_WIDTH-1:4];
      assign rd_hi = |s_axil_araddr[ADDR_WIDTH-1:4];
    end else begin : g_no_hi_bits
      assign wr_hi = 1'b0;
      assign rd_hi = 1'b0;
    end
  endgenerate

  // The last cycle of a count: EN set and COUNT at 1 or 0.
  wire count_end = en_q && (count_q[31:1] == 31'd0);

  always @* begin
    case (rd_idx)
      IDX_CTRL:   rd_value = {29'd0, mode_q, ie_q, en_q};
      IDX_LOAD:   rd_value = load_q;
      IDX_COUNT:  rd_value = count_q;
      IDX_STATUS: rd_value = {31'd0, expired_q};
      default:    rd_value = 32'd0;
    endcase
  end

  // ------------------------------------------------------------------
  // Next state
  // ------------------------------------------------------------------
  always @* begin
    aw_held_d = aw_held_q;
    w_held_d  = w_held_q;
    awaddr_d  = awaddr_q;
    wdata_d   = wdata_q;
    wstrb_d   = wstrb_q;
    bvalid_d  = bvalid_q;
    bresp_d   = bresp_q;
    rvalid_d  = rvalid_q;
    rdata_d   = rdata_q;
    rresp_d   = rresp_q;
    en_d      = en_q;
    ie_d      = ie_q;
    mode_d    = mode_q;
    expired_d = expired_q;
    load_d    = load_q;
    count_d   = count_q;

    // Hold an address or data that arrived alone; clear both on completion.
    if (do_write) begin
      aw_held_d = 1'b0;
      w_held_d  = 1'b0;
    end else begin
      if (aw_hs) begin
        aw_held_d = 1'b1;
        awaddr_d  = s_axil_awaddr;
      end
      if (w_hs) begin
        w_held_d = 1'b1;
        wdata_d  = s_axil_wdata;
        wstrb_d  = s_axil_wstrb;
      end
    end

    // Write response.
    if (do_write) begin
      bvalid_d = 1'b1;
      bresp_d  = wr_okay ? RESP_OKAY : RESP_SLVERR;
    end else if (bvalid_q && s_axil_bready) begin
      bvalid_d = 1'b0;
    end

    // Read response: the register value before the accepting edge.
    if (ar_hs) begin
      rvalid_d = 1'b1;
      rdata_d  = rd_mapped ? rd_value : 32'd0;
      rresp_d  = rd_mapped ? RESP_OKAY : RESP_SLVERR;
    end else if (rvalid_q && s_axil_rready) begin
      rvalid_d = 1'b0;
    end

    // 1. Count step: decrement, reload (periodic) or stop (one-shot).
    if (en_q) begin
      if (count_end) begin
        if (mode_q) begin
          count_d = load_q;
        end else begin
          count_d = 32'd0;
          en_d    = 1'b0;
        end
      end else begin
        count_d = count_q - 32'd1;
      end
    end

    // 2. EXPIRED: clear first, then set, so a count end beats a clear.
    if (status_clr) begin
      expired_d = 1'b0;
    end
    if (count_end) begin
      expired_d = 1'b1;
    end

    // 3. CTRL write (only with wstrb[0]); wins over the count step.
    if (ctrl_wr) begin
      en_d   = wr_data[0];
      ie_d   = wr_data[1];
      mode_d = wr_data[2];
      if (wr_data[0]) begin
        count_d = load_q;
      end
    end

    // 4. LOAD write: merge the strobed bytes.
    if (load_wr) begin
      if (wr_strb[0]) load_d[7:0]   = wr_data[7:0];
      if (wr_strb[1]) load_d[15:8]  = wr_data[15:8];
      if (wr_strb[2]) load_d[23:16] = wr_data[23:16];
      if (wr_strb[3]) load_d[31:24] = wr_data[31:24];
    end
  end

  // ------------------------------------------------------------------
  // Registers: synchronous, active-low reset
  // ------------------------------------------------------------------
  always @(posedge aclk) begin
    if (!aresetn) begin
      aw_held_q <= 1'b0;
      w_held_q  <= 1'b0;
      awaddr_q  <= {ADDR_WIDTH{1'b0}};
      wdata_q   <= 32'd0;
      wstrb_q   <= 4'd0;
      bvalid_q  <= 1'b0;
      bresp_q   <= RESP_OKAY;
      rvalid_q  <= 1'b0;
      rdata_q   <= 32'd0;
      rresp_q   <= RESP_OKAY;
      en_q      <= 1'b0;
      ie_q      <= 1'b0;
      mode_q    <= 1'b0;
      expired_q <= 1'b0;
      load_q    <= 32'd0;
      count_q   <= 32'd0;
    end else begin
      aw_held_q <= aw_held_d;
      w_held_q  <= w_held_d;
      awaddr_q  <= awaddr_d;
      wdata_q   <= wdata_d;
      wstrb_q   <= wstrb_d;
      bvalid_q  <= bvalid_d;
      bresp_q   <= bresp_d;
      rvalid_q  <= rvalid_d;
      rdata_q   <= rdata_d;
      rresp_q   <= rresp_d;
      en_q      <= en_d;
      ie_q      <= ie_d;
      mode_q    <= mode_d;
      expired_q <= expired_d;
      load_q    <= load_d;
      count_q   <= count_d;
    end
  end

  // ------------------------------------------------------------------
  // Outputs
  // ------------------------------------------------------------------
  assign s_axil_awready = awready_w;
  assign s_axil_wready  = wready_w;
  assign s_axil_bvalid  = bvalid_q;
  assign s_axil_bresp   = bresp_q;
  assign s_axil_arready = arready_w;
  assign s_axil_rvalid  = rvalid_q;
  assign s_axil_rdata   = rdata_q;
  assign s_axil_rresp   = rresp_q;
  assign irq            = expired_q && ie_q;

`ifdef FORMAL
  // Design-intent invariants (not a proof setup).
  reg f_reset_seen = 1'b0;
  always @(posedge aclk) begin
    if (!aresetn) begin
      f_reset_seen <= 1'b1;
    end
  end
  always @(*) begin
    if (f_reset_seen) begin
      assert (!(aw_held_q && w_held_q));
      assert (!(bvalid_q && (aw_held_q || w_held_q)));
      assert ((bresp_q == RESP_OKAY) || (bresp_q == RESP_SLVERR));
      assert ((rresp_q == RESP_OKAY) || (rresp_q == RESP_SLVERR));
    end
  end
`endif

endmodule

`default_nettype wire
=== END FILE ===
