// Self-checking testbench for axil_timer. Two lanes run in parallel,
// ADDR_WIDTH 4 and ADDR_WIDTH 8; the top prints one verdict.
module axil_timer_tb;
  reg clk = 1'b0;
  always #5 clk = ~clk;

  wire [31:0] passed_aw4;
  wire [31:0] failed_aw4;
  wire [31:0] passed_aw8;
  wire [31:0] failed_aw8;
  wire        done_aw4;
  wire        done_aw8;

  axil_timer_tb_core #(.AW(4)) u_core_aw4 (
      .clk(clk), .passed(passed_aw4), .failed(failed_aw4), .done(done_aw4));
  axil_timer_tb_core #(.AW(8)) u_core_aw8 (
      .clk(clk), .passed(passed_aw8), .failed(failed_aw8), .done(done_aw8));

  reg [8*64-1:0] nonce;
  reg [31:0]     passed;
  reg [31:0]     failed;
  reg [31:0]     cycles;

  initial begin
    nonce  = {8*64{1'b0}};
    passed = 32'd0;
    failed = 32'd0;
    cycles = 32'd0;
    if ($value$plusargs("nirmaan_nonce=%s", nonce) == 0) begin
      nonce = "no-nonce";
    end
    while (((done_aw4 & done_aw8) !== 1'b1) && (cycles < 32'd200000)) begin
      @(posedge clk);
      cycles = cycles + 32'd1;
    end
    passed = passed_aw4 + passed_aw8;
    failed = failed_aw4 + failed_aw8;
    if ((done_aw4 & done_aw8) !== 1'b1) begin
      failed = failed + 32'd1;
      $error("axil_timer_tb: timeout before both lanes finished");
    end
    $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
    $finish;
  end
endmodule

module axil_timer_tb_core #(
    parameter integer AW = 4
) (
    input  wire        clk,
    output reg  [31:0] passed,
    output reg  [31:0] failed,
    output reg         done
);
  localparam [1:0]   OKAY   = 2'b00;
  localparam [1:0]   SLVERR = 2'b10;
  localparam integer MSG_W  = 8 * 72;
  localparam [7:0]   A_LOAD = 8'h04;

  reg           aresetn;
  reg  [AW-1:0] awaddr;
  reg           awvalid;
  wire          awready;
  reg  [31:0]   wdata;
  reg  [3:0]    wstrb;
  reg           wvalid;
  wire          wready;
  wire [1:0]    bresp;
  wire          bvalid;
  reg           bready;
  reg  [AW-1:0] araddr;
  reg           arvalid;
  wire          arready;
  wire [31:0]   rdata;
  wire [1:0]    rresp;
  wire          rvalid;
  reg           rready;
  wire          irq;

  axil_timer #(.ADDR_WIDTH(AW)) dut (
      .aclk(clk), .aresetn(aresetn),
      .s_axil_awaddr(awaddr), .s_axil_awvalid(awvalid), .s_axil_awready(awready),
      .s_axil_wdata(wdata), .s_axil_wstrb(wstrb), .s_axil_wvalid(wvalid),
      .s_axil_wready(wready),
      .s_axil_bresp(bresp), .s_axil_bvalid(bvalid), .s_axil_bready(bready),
      .s_axil_araddr(araddr), .s_axil_arvalid(arvalid), .s_axil_arready(arready),
      .s_axil_rdata(rdata), .s_axil_rresp(rresp), .s_axil_rvalid(rvalid),
      .s_axil_rready(rready),
      .irq(irq));

  // Edge counter and irq monitor, sampled 1 ns after each rising edge.
  integer edge_cnt      = 0;
  integer irq_rises     = 0;
  integer irq_falls     = 0;
  integer irq_rise_edge = 0;
  integer irq_fall_edge = 0;
  reg     irq_q         = 1'b0;

  always @(posedge clk) begin
    #1;
    edge_cnt = edge_cnt + 1;
    if (irq && !irq_q) begin
      irq_rises     = irq_rises + 1;
      irq_rise_edge = edge_cnt;
    end
    if (!irq && irq_q) begin
      irq_falls     = irq_falls + 1;
      irq_fall_edge = edge_cnt;
    end
    irq_q = irq;
  end

  // ------------------------------------------------------------------
  // Check helpers
  // ------------------------------------------------------------------
  task check(input cond, input [MSG_W-1:0] msg);
    begin
      if (cond === 1'b1) begin
        passed = passed + 32'd1;
      end else begin
        failed = failed + 32'd1;
        $error("axil_timer_tb AW=%0d edge %0d: %0s", AW, edge_cnt, msg);
      end
    end
  endtask

  task check_eq(input [31:0] act, input [31:0] expv, input [MSG_W-1:0] msg);
    begin
      if (act === expv) begin
        passed = passed + 32'd1;
      end else begin
        failed = failed + 32'd1;
        $error("axil_timer_tb AW=%0d edge %0d: %0s: got %0d (0x%08h), expected %0d (0x%08h)",
               AW, edge_cnt, msg, act, act, expv, expv);
      end
    end
  endtask

  // ------------------------------------------------------------------
  // AXI4-Lite manager tasks. Called at a falling edge; return at one.
  // ------------------------------------------------------------------
  reg [1:0]  wr_resp;
  integer    wr_edge;
  reg [31:0] rd_data;
  reg [1:0]  rd_resp;
  integer    rd_edge;

  task axi_write_t(input [7:0] addr, input [31:0] data, input [3:0] strb,
                   input integer aw_dly, input integer w_dly, input integer b_dly);
    integer   cyc;
    integer   bcnt;
    reg       aw_done;
    reg       w_done;
    reg       b_done;
    reg       b_seen;
    reg       fire_aw;
    reg       fire_w;
    reg       fire_b;
    reg [1:0] resp_hold;
    begin
      cyc       = 0;
      bcnt      = 0;
      aw_done   = 1'b0;
      w_done    = 1'b0;
      b_done    = 1'b0;
      b_seen    = 1'b0;
      resp_hold = 2'b00;
      awaddr    = addr[AW-1:0];
      wdata     = data;
      wstrb     = strb;
      while (!b_done) begin
        awvalid = !aw_done && (cyc >= aw_dly);
        wvalid  = !w_done && (cyc >= w_dly);
        if (bvalid) begin
          if (!b_seen) begin
            b_seen    = 1'b1;
            wr_edge   = edge_cnt;
            resp_hold = bresp;
            check(aw_done && w_done, "BVALID rises only after both AW and W are accepted");
          end else begin
            check(bresp == resp_hold, "BRESP holds while BVALID waits for BREADY");
          end
          check(!awready && !wready, "no write accepted while BVALID is high");
          bready = (bcnt >= b_dly);
          bcnt   = bcnt + 1;
        end else begin
          bready = (b_dly == 0);
          if (aw_done && w_done) begin
            check(1'b0, "BVALID rises on the edge the write completes");
          end
          if (aw_done && !w_done) begin
            check(!awready, "AWREADY low while a write address is held");
          end
          if (w_done && !aw_done) begin
            check(!wready, "WREADY low while write data is held");
          end
        end
        #1;
        fire_aw = awvalid && awready;
        fire_w  = wvalid && wready;
        fire_b  = bvalid && bready;
        @(posedge clk);
        @(negedge clk);
        if (fire_aw) aw_done = 1'b1;
        if (fire_w)  w_done  = 1'b1;
        if (fire_b)  b_done  = 1'b1;
        cyc = cyc + 1;
        if (cyc > 300) begin
          check(1'b0, "write transaction timed out");
          b_done = 1'b1;
        end
      end
      awvalid = 1'b0;
      wvalid  = 1'b0;
      bready  = 1'b0;
      wr_resp = resp_hold;
    end
  endtask

  task axi_read_t(input [7:0] addr, input integer ar_dly, input integer r_dly);
    integer cyc;
    integer rcnt;
    reg     ar_done;
    reg     r_done;
    reg     r_seen;
    reg     fire_ar;
    reg     fire_r;
    begin
      cyc     = 0;
      rcnt    = 0;
      ar_done = 1'b0;
      r_done  = 1'b0;
      r_seen  = 1'b0;
      rd_edge = -1;
      araddr  = addr[AW-1:0];
      while (!r_done) begin
        arvalid = !ar_done && (cyc >= ar_dly);
        if (rvalid) begin
          if (!r_seen) begin
            r_seen  = 1'b1;
            rd_data = rdata;
            rd_resp = rresp;
            check(ar_done, "RVALID rises only after the read address is accepted");
            check(edge_cnt == rd_edge, "RVALID rises on the edge AR is accepted");
          end else begin
            check((rdata == rd_data) && (rresp == rd_resp),
                  "RDATA and RRESP hold while RVALID waits for RREADY");
          end
          check(!arready, "ARREADY low while RVALID is high");
          rready = (rcnt >= r_dly);
          rcnt   = rcnt + 1;
        end else begin
          rready = (r_dly == 0);
          if (ar_done) begin
            check(1'b0, "RVALID rises on the edge AR is accepted");
          end
        end
        #1;
        fire_ar = arvalid && arready;
        fire_r  = rvalid && rready;
        @(posedge clk);
        @(negedge clk);
        if (fire_ar) begin
          ar_done = 1'b1;
          rd_edge = edge_cnt;
        end
        if (fire_r) r_done = 1'b1;
        cyc = cyc + 1;
        if (cyc > 300) begin
          check(1'b0, "read transaction timed out");
          r_done = 1'b1;
        end
      end
      arvalid = 1'b0;
      rready  = 1'b0;
    end
  endtask

  task wr(input [7:0] addr, input [31:0] data, input [3:0] strb, input [1:0] exp_resp);
    begin
      axi_write_t(addr, data, strb, 0, 0, 0);
      if (wr_resp === exp_resp) begin
        passed = passed + 32'd1;
      end else begin
        failed = failed + 32'd1;
        $error("axil_timer_tb AW=%0d write 0x%02h: BRESP %b, expected %b",
               AW, addr, wr_resp, exp_resp);
      end
    end
  endtask

  task rd_expect(input [7:0] addr, input [31:0] expv, input [1:0] exp_resp);
    begin
      axi_read_t(addr, 0, 0);
      if ((rd_data === expv) && (rd_resp === exp_resp)) begin
        passed = passed + 32'd1;
      end else begin
        failed = failed + 32'd1;
        $error("axil_timer_tb AW=%0d read 0x%02h: got 0x%08h/%b, expected 0x%08h/%b",
               AW, addr, rd_data, rd_resp, expv, exp_resp);
      end
    end
  endtask

  task idle(input integer n);
    integer i;
    begin
      for (i = 0; i < n; i = i + 1) begin
        @(negedge clk);
      end
    end
  endtask

  task wait_until(input integer target);
    begin
      check(edge_cnt <= target, "test schedule: target edge is still ahead");
      while (edge_cnt < target) begin
        @(negedge clk);
      end
    end
  endtask

  task wait_rise(input integer prev, input integer limit);
    integer n;
    begin
      n = 0;
      while ((irq_rises == prev) && (n < limit)) begin
        @(negedge clk);
        n = n + 1;
      end
      check(irq_rises == prev + 1, "irq rose exactly once while waiting");
    end
  endtask

  task do_reset;
    begin
      aresetn = 1'b0;
      awvalid = 1'b0;
      wvalid  = 1'b0;
      bready  = 1'b0;
      arvalid = 1'b0;
      rready  = 1'b0;
      repeat (3) @(negedge clk);
      aresetn = 1'b1;
    end
  endtask

  task oneshot_run(input [31:0] n_load);
    integer e0;
    integer r0;
    integer n_eff;
    begin
      n_eff = (n_load == 32'd0) ? 1 : n_load;
      wr(8'h04, n_load, 4'hF, OKAY);
      r0 = irq_rises;
      wr(8'h00, 32'h0000_0003, 4'h1, OKAY);
      e0 = wr_edge;
      wait_rise(r0, n_eff + 20);
      check_eq(irq_rise_edge, e0 + n_eff, "one-shot ends LOAD edges after the start");
      rd_expect(8'h00, 32'h0000_0002, OKAY);
      rd_expect(8'h08, 32'h0000_0000, OKAY);
      rd_expect(8'h0C, 32'h0000_0001, OKAY);
      check(irq === 1'b1, "irq stays high while EXPIRED and IE");
      wr(8'h0C, 32'h0000_0000, 4'hF, OKAY);
      rd_expect(8'h0C, 32'h0000_0001, OKAY);
      wr(8'h0C, 32'h0000_0001, 4'hE, OKAY);
      rd_expect(8'h0C, 32'h0000_0001, OKAY);
      wr(8'h0C, 32'h0000_0001, 4'h1, OKAY);
      rd_expect(8'h0C, 32'h0000_0000, OKAY);
      check(irq === 1'b0, "irq low after EXPIRED is cleared");
      idle(n_eff + 20);
      check(irq_rises == r0 + 1, "a one-shot raises no second interrupt");
      rd_expect(8'h0C, 32'h0000_0000, OKAY);
      rd_expect(8'h00, 32'h0000_0002, OKAY);
    end
  endtask

  // ------------------------------------------------------------------
  // Directed sequence
  // ------------------------------------------------------------------
  integer e;
  integer s;
  integer r2;
  integer r0;
  integer f0;
  integer k;
  integer j;

  initial begin
    passed  = 32'd0;
    failed  = 32'd0;
    done    = 1'b0;
    aresetn = 1'b0;
    awaddr  = {AW{1'b0}};
    awvalid = 1'b0;
    wdata   = 32'd0;
    wstrb   = 4'd0;
    wvalid  = 1'b0;
    bready  = 1'b0;
    araddr  = {AW{1'b0}};
    arvalid = 1'b0;
    rready  = 1'b0;
    wr_resp = 2'b00;
    wr_edge = 0;
    rd_data = 32'd0;
    rd_resp = 2'b00;
    rd_edge = 0;

    @(negedge clk);
    do_reset;

    // T1: reset values
    check((awready === 1'b1) && (wready === 1'b1) && (arready === 1'b1),
          "AWREADY, WREADY and ARREADY high after reset");
    check((bvalid === 1'b0) && (rvalid === 1'b0), "BVALID and RVALID low after reset");
    check(irq === 1'b0, "irq low after reset");
    rd_expect(8'h00, 32'h0, OKAY);
    rd_expect(8'h04, 32'h0, OKAY);
    rd_expect(8'h08, 32'h0, OKAY);
    rd_expect(8'h0C, 32'h0, OKAY);

    // T2: LOAD with partial and empty strobes
    wr(8'h04, 32'hFFFF_FFFF, 4'hF, OKAY);
    rd_expect(8'h04, 32'hFFFF_FFFF, OKAY);
    wr(8'h04, 32'h1234_5678, 4'b0101, OKAY);
    rd_expect(8'h04, 32'hFF34_FF78, OKAY);
    wr(8'h04, 32'h0000_0000, 4'b1000, OKAY);
    rd_expect(8'h04, 32'h0034_FF78, OKAY);
    wr(8'h04, 32'hAAAA_AAAA, 4'b0000, OKAY);
    rd_expect(8'h04, 32'h0034_FF78, OKAY);
    wr(8'h04, 32'hA5A5_A5A5, 4'b0010, OKAY);
    rd_expect(8'h04, 32'h0034_A578, OKAY);

    // T3: channel orders, back-pressure, concurrent read and write
    axi_write_t(8'h04, 32'h1111_1111, 4'hF, 0, 3, 0);
    check(wr_resp == OKAY, "BRESP OKAY, AW before W");
    rd_expect(8'h04, 32'h1111_1111, OKAY);
    axi_write_t(8'h04, 32'h2222_2222, 4'hF, 4, 0, 3);
    check(wr_resp == OKAY, "BRESP OKAY, W before AW, BREADY held off");
    rd_expect(8'h04, 32'h2222_2222, OKAY);
    axi_write_t(8'h04, 32'h3333_3333, 4'hF, 0, 0, 5);
    check(wr_resp == OKAY, "BRESP OKAY, AW and W together, BREADY held off");
    axi_read_t(8'h04, 2, 4);
    check_eq(rd_data, 32'h3333_3333, "LOAD read with ARVALID delay and RREADY held off");
    check(rd_resp == OKAY, "RRESP OKAY with RREADY held off");
    fork
      axi_write_t(8'h04, 32'h4444_4444, 4'hF, 0, 0, 2);
      axi_read_t(8'h00, 0, 1);
    join
    check(wr_resp == OKAY, "BRESP OKAY with a concurrent read");
    check_eq(rd_data, 32'h0, "CTRL read concurrent with a LOAD write");
    rd_expect(8'h04, 32'h4444_4444, OKAY);
    fork
      axi_write_t(8'h04, 32'h5555_5555, 4'hF, 0, 0, 0);
      axi_read_t(8'h04, 0, 0);
    join
    check_eq(rd_data, 32'h4444_4444, "read on the write edge returns the old LOAD");
    rd_expect(8'h04, 32'h5555_5555, OKAY);

    // T4: CTRL write without wstrb[0]
    wr(8'h00, 32'h0000_0007, 4'b1110, OKAY);
    rd_expect(8'h00, 32'h0, OKAY);
    idle(5);
    rd_expect(8'h08, 32'h0, OKAY);
    check(irq === 1'b0, "CTRL write without wstrb[0] starts nothing");

    // T5: COUNT read only and the SLVERR policy
    wr(8'h08, 32'h0000_0055, 4'hF, SLVERR);
    rd_expect(8'h08, 32'h0, OKAY);
    wr(8'h05, 32'hDEAD_BEEF, 4'hF, SLVERR);
    rd_expect(8'h04, 32'h5555_5555, OKAY);
    wr(8'h01, 32'h0000_0003, 4'hF, SLVERR);
    rd_expect(8'h00, 32'h0, OKAY);
    wr(8'h0E, 32'hFFFF_FFFF, 4'hF, SLVERR);
    rd_expect(8'h05, 32'h0, SLVERR);
    rd_expect(8'h06, 32'h0, SLVERR);
    rd_expect(8'h07, 32'h0, SLVERR);
    rd_expect(8'h0D, 32'h0, SLVERR);
    if (AW > 4) begin
      wr(8'h14, 32'hCAFE_F00D, 4'hF, SLVERR);
      rd_expect(8'h04, 32'h5555_5555, OKAY);
      wr(8'h10, 32'h0000_0003, 4'hF, SLVERR);
      rd_expect(8'h00, 32'h0, OKAY);
      wr(8'h18, 32'h0000_0055, 4'hF, SLVERR);
      wr(8'h1C, 32'h0000_0001, 4'hF, SLVERR);
      wr(8'hF4, 32'h0000_1234, 4'hF, SLVERR);
      rd_expect(8'h04, 32'h5555_5555, OKAY);
      rd_expect(8'h10, 32'h0, SLVERR);
      rd_expect(8'h14, 32'h0, SLVERR);
      rd_expect(8'h84, 32'h0, SLVERR);
      rd_expect(8'hFC, 32'h0, SLVERR);
      idle(5);
      rd_expect(8'h08, 32'h0, OKAY);
      check(irq === 1'b0, "unmapped writes start no count");
    end

    // T6: one-shot counts timed to the cycle
    oneshot_run(32'd5);
    oneshot_run(32'd1);
    oneshot_run(32'd0);
    oneshot_run(32'd2);
    oneshot_run(32'd200);

    // T7: interrupt enable on a pending expiry
    wr(8'h04, 32'd3, 4'hF, OKAY);
    r0 = irq_rises;
    wr(8'h00, 32'h0000_0001, 4'h1, OKAY);
    e = wr_edge;
    wait_until(e + 10);
    check(irq_rises == r0, "no interrupt while IE is 0");
    check(irq === 1'b0, "irq low while IE is 0");
    rd_expect(8'h0C, 32'h1, OKAY);
    rd_expect(8'h00, 32'h0, OKAY);
    wr(8'h00, 32'h0000_0002, 4'h1, OKAY);
    check_eq(irq_rises, r0 + 1, "irq rises when IE is written 1");
    check_eq(irq_rise_edge, wr_edge, "irq rises on the edge IE is written 1");
    rd_expect(8'h00, 32'h2, OKAY);
    f0 = irq_falls;
    wr(8'h00, 32'h0000_0000, 4'h1, OKAY);
    check_eq(irq_falls, f0 + 1, "irq falls when IE is written 0");
    check_eq(irq_fall_edge, wr_edge, "irq falls on the edge IE is written 0");
    rd_expect(8'h0C, 32'h1, OKAY);
    wr(8'h0C, 32'h1, 4'h1, OKAY);
    rd_expect(8'h0C, 32'h0, OKAY);

    // T8: periodic counts over several periods
    wr(8'h04, 32'd10, 4'hF, OKAY);
    r0 = irq_rises;
    wr(8'h00, 32'h0000_0007, 4'h1, OKAY);
    e = wr_edge;
    for (k = 1; k <= 3; k = k + 1) begin
      wait_rise(r0 + k - 1, 30);
      check_eq(irq_rise_edge, e + 10 * k, "periodic count ends every LOAD edges");
      rd_expect(8'h00, 32'h7, OKAY);
      wr(8'h0C, 32'h1, 4'h1, OKAY);
      check(irq === 1'b0, "irq low after a periodic expiry is cleared");
      axi_read_t(8'h08, 0, 0);
      j = rd_edge - 1 - e;
      check_eq(rd_data, 10 - (j % 10), "COUNT read during a periodic count");
    end
    wait_rise(r0 + 3, 30);
    check_eq(irq_rise_edge, e + 40, "fourth periodic count end");
    f0 = irq_falls;
    wait_until(e + 49);
    wr(8'h0C, 32'h1, 4'h1, OKAY);
    check_eq(wr_edge, e + 50, "STATUS clear lands on the count-end edge");
    check_eq(irq_falls, f0, "a count end beats a clear: irq stays high");
    rd_expect(8'h0C, 32'h1, OKAY);
    wr(8'h0C, 32'h1, 4'h1, OKAY);
    check_eq(irq_falls, f0 + 1, "irq falls after a later clear");
    wait_rise(r0 + 4, 30);
    check_eq(irq_rise_edge, e + 60, "period kept after a clear on the end edge");
    wr(8'h00, 32'h0000_0002, 4'h1, OKAY);
    wr(8'h0C, 32'h1, 4'h1, OKAY);
    idle(30);
    check(irq_rises == r0 + 5, "no expiry after the periodic count is stopped");
    rd_expect(8'h00, 32'h2, OKAY);

    // T9: a stop freezes COUNT
    wr(8'h04, 32'd100, 4'hF, OKAY);
    r0 = irq_rises;
    wr(8'h00, 32'h0000_0003, 4'h1, OKAY);
    e = wr_edge;
    idle(10);
    wr(8'h00, 32'h0000_0002, 4'h1, OKAY);
    s = wr_edge;
    rd_expect(8'h08, 100 - (s - e), OKAY);
    idle(20);
    rd_expect(8'h08, 100 - (s - e), OKAY);
    rd_expect(8'h00, 32'h2, OKAY);
    wr(8'h08, 32'h1234_5678, 4'hF, SLVERR);
    rd_expect(8'h08, 100 - (s - e), OKAY);
    wait_until(e + 130);
    check(irq_rises == r0, "a stopped count never ends");
    rd_expect(8'h0C, 32'h0, OKAY);

    // T10: restart, restart on the end edge, stop on the end edge
    wr(8'h04, 32'd20, 4'hF, OKAY);
    r0 = irq_rises;
    wr(8'h00, 32'h0000_0003, 4'h1, OKAY);
    e = wr_edge;
    idle(5);
    wr(8'h00, 32'h0000_0003, 4'h1, OKAY);
    r2 = wr_edge;
    wait_rise(r0, 40);
    check_eq(irq_rise_edge, r2 + 20, "a restart counts LOAD edges from the restart");
    wr(8'h0C, 32'h1, 4'h1, OKAY);

    wr(8'h04, 32'd10, 4'hF, OKAY);
    r0 = irq_rises;
    wr(8'h00, 32'h0000_0003, 4'h1, OKAY);
    e = wr_edge;
    wait_until(e + 9);
    wr(8'h00, 32'h0000_0003, 4'h1, OKAY);
    check_eq(wr_edge, e + 10, "restart write lands on the count-end edge");
    check_eq(irq_rises, r0 + 1, "EXPIRED set by the count that ended");
    check_eq(irq_rise_edge, e + 10, "EXPIRED set on the count-end edge");
    rd_expect(8'h00, 32'h3, OKAY);
    wr(8'h0C, 32'h1, 4'h1, OKAY);
    check(irq === 1'b0, "irq low after clearing the restart-edge expiry");
    wait_rise(r0 + 1, 30);
    check_eq(irq_rise_edge, e + 20, "restart on the end edge counts LOAD again");
    rd_expect(8'h00, 32'h2, OKAY);
    wr(8'h0C, 32'h1, 4'h1, OKAY);

    wr(8'h04, 32'd10, 4'hF, OKAY);
    r0 = irq_rises;
    wr(8'h00, 32'h0000_0007, 4'h1, OKAY);
    e = wr_edge;
    wait_until(e + 9);
    wr(8'h00, 32'h0000_0006, 4'h1, OKAY);
    check_eq(wr_edge, e + 10, "stop write lands on the count-end edge");
    check_eq(irq_rise_edge, e + 10, "EXPIRED still set by the ending count");
    rd_expect(8'h08, 32'd10, OKAY);
    rd_expect(8'h00, 32'h6, OKAY);
    wr(8'h0C, 32'h1, 4'h1, OKAY);
    idle(30);
    check(irq_rises == r0 + 1, "no count end after a stop on the end edge");
    rd_expect(8'h08, 32'd10, OKAY);
    rd_expect(8'h0C, 32'h0, OKAY);

    // T11: reset during a count, with a write address held
    wr(8'h04, 32'd50, 4'hF, OKAY);
    r0 = irq_rises;
    wr(8'h00, 32'h0000_0003, 4'h1, OKAY);
    idle(10);
    awaddr  = A_LOAD[AW-1:0];
    awvalid = 1'b1;
    #1;
    check(awready === 1'b1, "AWREADY high before a lone address");
    @(posedge clk);
    @(negedge clk);
    awvalid = 1'b0;
    check(awready === 1'b0, "lone write address is held");
    do_reset;
    check((awready === 1'b1) && (wready === 1'b1) && (arready === 1'b1),
          "reset clears held requests and readies return high");
    check((bvalid === 1'b0) && (rvalid === 1'b0), "BVALID and RVALID low after reset");
    check(irq === 1'b0, "irq low after reset during a count");
    rd_expect(8'h00, 32'h0, OKAY);
    rd_expect(8'h04, 32'h0, OKAY);
    rd_expect(8'h08, 32'h0, OKAY);
    rd_expect(8'h0C, 32'h0, OKAY);
    idle(70);
    check(irq_rises == r0, "no expiry after reset stopped the count");
    rd_expect(8'h0C, 32'h0, OKAY);
    rd_expect(8'h08, 32'h0, OKAY);
    wr(8'h04, 32'h0000_0009, 4'hF, OKAY);
    rd_expect(8'h04, 32'h0000_0009, OKAY);

    done = 1'b1;
  end
endmodule

`default_nettype wire
